import numpy as np
# MECHANISM: Introduce a preference for already-used bins over empty ones to encourage faster filling.

def priority(item, bins):
    used_bins = bins != 150
    preference = used_bins.astype(float)
    return np.array([preference[i] + (150 - bins[i] - item) for i in range(len(bins))])

